mapper.select:
SELECT g.id AS `id`, g.created_at AS `createdAt`, g.round_id AS `roundId`, g.game_code AS `gameCode`, g.billing_type AS `billingType`, g.result AS `result`, g.rebate AS `rebate`, g.settlement AS `settlement`, g.operator AS `operator`, IFNULL(c.bets_number, 0) AS `betsNumber`, IFNULL(c.bets_amount, 0) AS `betsAmount`, IFNULL(c.winners, 0) AS `winners`, IFNULL(c.bets_amount - c.total_expenses, 0) AS `winOrLoss` FROM lms_game_record g LEFT JOIN ( SELECT round_id, channel_id, game_code, COUNT(DISTINCT user_id) AS bets_number, IFNULL(SUM(bet), 0) AS bets_amount, COUNT(DISTINCT IF(settlement_multiple > 0, user_id, NULL)) AS winners, IFNULL(SUM(IF(settlement_multiple > 0, pay_out, 0)), 0) AS total_expenses FROM lms_coin_record WHERE user_id >= 10000 GROUP BY round_id, channel_id, game_code ) c ON g.round_id = c.round_id AND g.channel_id = c.channel_id AND g.game_code <=> c.game_code WHERE 1=1
AND g.billing_type = #{billingType}
AND g.round_id = #{roundId}
AND g.game_code IS NULL AND g.game_code = #{gameCode}
AND g.created_at BETWEEN #{startAt} AND #{endAt}
AND g.channel_id IN
#{cid}
ORDER BY g.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM lms_game_record g
WHERE 1=1

    AND g.billing_type = #{billingType}


    AND g.round_id = #{roundId}


    AND g.game_code IS NULL
    AND g.game_code = #{gameCode}


    AND g.created_at BETWEEN #{startAt} AND #{endAt}


    AND g.channel_id IN

        #{cid}

SELECT IFNULL(SUM(bet), 0) AS `totalBets`, IFNULL(SUM(IF(settlement_multiple > 0, pay_out, 0)), 0) AS `totalExpenses` FROM lms_coin_record WHERE user_id >= 10000
AND game_code IS NULL AND game_code = #{gameCode}
AND channel_id IN
#{cid}

SELECT
    IFNULL(SUM(cr.bet), 0) AS `totalBets`,
    IFNULL(SUM(IF(cr.settlement_multiple > 0, cr.pay_out, 0)), 0) AS `totalExpenses`
FROM lms_coin_record cr
INNER JOIN lms_game_record g ON g.round_id = cr.round_id AND g.channel_id = cr.channel_id AND g.game_code <=> cr.game_code
WHERE cr.user_id >= 10000

    AND g.billing_type = #{billingType}


    AND g.round_id = #{roundId}


    AND g.game_code IS NULL
    AND g.game_code = #{gameCode}


    AND g.created_at BETWEEN #{startAt} AND #{endAt}


    AND cr.channel_id IN

        #{cid}
